// Sandbox-only browser portal. No external scripts, cookies, token persistence,
// or automatic payment retries. The customer JWT is supplied through test MFA.
import {createHash} from "node:crypto";
const css="body{font:16px system-ui;background:#f3f6fa;color:#18263a;margin:0}main{max-width:640px;margin:auto;padding:24px}section{background:white;border:1px solid #d8e1ec;padding:20px;border-radius:12px;margin-top:16px}label{display:block;margin:12px 0 4px}input:not([type=checkbox]),select{box-sizing:border-box;width:100%;padding:12px;border:1px solid #a8b7cc;border-radius:6px;font:inherit}button{font:inherit;padding:12px 16px;border:0;border-radius:6px;background:#174b87;color:white;margin:12px 8px 0 0}button:disabled{opacity:.45}p{line-height:1.5;overflow-wrap:anywhere}.notice{border-left:4px solid #a66c13;background:#fff3db;padding:12px}.amount{font-size:30px;font-weight:700}dt{font-weight:600}dd{margin:0 0 12px}img{display:block;max-width:100%;height:auto;margin:12px 0;border-radius:8px}iframe{width:100%;min-height:640px;border:1px solid #d8e1ec;border-radius:8px}";
function page(title,markup,script){
 const hash=createHash("sha256").update(script).digest("base64");
 const csp="default-src 'none'; script-src 'sha256-"+hash+"'; style-src 'unsafe-inline'; connect-src 'self'; img-src data:; frame-src 'self' about:; base-uri 'none'; form-action 'none'; frame-ancestors 'none'";
 return {csp,html:"<!doctype html><html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width, initial-scale=1\"><title>"+title+"</title><style>"+css+"</style></head><body><main>"+markup+"</main><script>"+script+"</script></body></html>"};
}
const portalScript=String.raw`
(()=>{
 const $=id=>document.getElementById(id),uuid=/^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$/;
 let token="",scope=null,view=null,busy=false,attemptKey=null,grant=null,completion=null;
 const message=s=>{$("message").textContent=s;};
 function clearView(){completion=null;$("evidence").replaceChildren();$("work-comments").textContent="";$("inspect").checked=false;$("approve-work").disabled=true;$("reject-work").disabled=true;$("open-dispute").disabled=true;$("rejection-reason").value="";view=null;scope=null;grant=null;attemptKey=null;$("new-pin").value="";$("step-up").value="";$("details").hidden=true;$("pin").value="";$("confirm").checked=false;$("reserve").disabled=true;}
 function controls(){for(const id of ["load","clear","grant","set-pin","tenant","milestone","token","load-evidence"])$(id).disabled=busy;$("approve-work").disabled=busy||!completion||view?.status!=="submitted"||!$("inspect").checked;$("reject-work").disabled=busy||!completion||view?.status!=="submitted";$("open-dispute").disabled=busy||!completion||!["planned","submitted","approved","release_pending"].includes(view?.status);$("reserve").disabled=busy||!view||view.status!=="approved"||view.fundingStatus!=="funded"||view.requestStatus!==null||!$("confirm").checked;}
 async function post(path,body){const r=await fetch("/v1/securepay"+path,{method:"POST",headers:{"Content-Type":"application/json","Authorization":"Bearer "+token},body:JSON.stringify(body),cache:"no-store",credentials:"omit",redirect:"error"});let x;try{x=await r.json();}catch{throw Error("Invalid service response");}return {code:r.status,data:x};}
 function cents(v){if(typeof v!=="string"||!/^[1-9][0-9]{0,18}$/.test(v))throw Error("Invalid amount");const n=BigInt(v);return "AUD $"+String(n/100n)+"."+String(n%100n).padStart(2,"0");}
 function valid(v,m){return v?.mode==="sandbox"&&v.moneyMoved===false&&v.milestoneId===m&&typeof v.amountCents==="string"&&/^[1-9][0-9]{0,18}$/.test(v.amountCents)&&["planned","submitted","approved","disputed","release_pending","released","settled","cancelled"].includes(v.status)&&["unfunded","funded","held","released","settled"].includes(v.fundingStatus)&&[null,"pending","submitted","confirmed","failed"].includes(v.requestStatus);}
 for(const id of ["tenant","milestone","token"])$(id).addEventListener("input",()=>{if(!busy){if(id==="token")token="";clearView();controls();}});
 $("load").addEventListener("click",async()=>{
  if(busy)return;const t=$("tenant").value.trim(),m=$("milestone").value.trim(),supplied=$("token").value.trim();$("token").value="";
  if(supplied)token=supplied;clearView();
  if(!uuid.test(t)||!uuid.test(m)||!token){message("Enter the tenant, milestone and sandbox MFA token.");return;}
  busy=true;controls();
  try{const r=await post("/tenants/"+t+"/milestones/"+m+"/view",{});if(r.code!==200||!valid(r.data,m)){message("Unable to access this milestone. Check your identity and session.");return;}
   view=r.data;scope={t,m};$("loaded-ref").textContent=m;$("amount").textContent=cents(view.amountCents);$("state").textContent=view.status;$("funding").textContent=view.fundingStatus;$("request").textContent=view.requestStatus??"None";$("details").hidden=false;message("Review the amount and current status before authorising.");
  }catch{message("Unable to load the milestone. No payment was submitted.");}finally{busy=false;controls();}
 });
 $("confirm").addEventListener("change",controls);
 $("inspect").addEventListener("change",controls);
 $("load-evidence").addEventListener("click",async()=>{
  if(busy||!scope||!view)return;
  busy=true;completion=null;$("evidence").replaceChildren();$("inspect").checked=false;$("work-comments").textContent="";controls();
  const path="/tenants/"+scope.t+"/milestones/"+scope.m;
  try{
   const r=await post(path+"/completion",{}),c=r.data;
   if(r.code!==200||c?.mode!=="sandbox"||c.moneyMoved!==false||!uuid.test(c.completionId)||!/^[a-f0-9]{64}$/.test(c.manifestDigest)||c.amountCents!==view.amountCents||!Array.isArray(c.photos)||c.photos.length<1||c.photos.length>12||typeof c.comments!=="string"||!/^(0|[1-9][0-9]{0,18})$/.test(c.version))throw Error("Evidence unavailable");
   $("work-comments").textContent=c.comments;
   for(const p of c.photos){
    if(!uuid.test(p.photoId)||!/^[a-f0-9]{64}$/.test(p.digest))throw Error("Invalid photo");
    const response=await post(path+"/photo",{photoId:p.photoId}),photo=response.data;
    if(response.code!==200||photo?.mode!=="sandbox"||photo.moneyMoved!==false||photo.photoId!==p.photoId||photo.digest!==p.digest||typeof photo.content!=="string"||photo.content.length>2796204||!/^[A-Za-z0-9+/]+={0,2}$/.test(photo.content))throw Error("Invalid photo");
    const img=document.createElement("img");img.alt="Submitted completion photograph";img.src="data:image/png;base64,"+photo.content;
    await img.decode();$("evidence").append(img);
   }
   completion=c;message("All completion photos loaded. Review the work before approving it.");
  }catch{$("evidence").replaceChildren();$("work-comments").textContent="";message("Completion evidence could not be loaded. Approval remains disabled.");}
  finally{busy=false;controls();}
 });
 $("approve-work").addEventListener("click",async()=>{
  if(busy||!scope||!completion||$("approve-work").disabled)return;
  if(BigInt(completion.amountCents)>BigInt(Number.MAX_SAFE_INTEGER)){message("Amount exceeds supported limits.");return;}
  busy=true;controls();
  try{
   const r=await post("/tenants/"+scope.t+"/milestones/"+scope.m+"/approve",{completionId:completion.completionId,manifestDigest:completion.manifestDigest,expectedAmountCents:Number(completion.amountCents),version:completion.version});
   message(r.code===200&&r.data?.status==="work_approved"&&r.data.moneyMoved===false?"Work approved. Reload the milestone before PIN authorisation.":"Approval not confirmed. Reload the milestone.");
  }catch{message("Approval outcome uncertain. Reload the milestone.");}
  finally{clearView();busy=false;controls();}
 });
 for(const [id,action] of [["reject-work","reject"],["open-dispute","dispute"]])$(id).addEventListener("click",async()=>{
  if(busy||!scope||!completion||$(id).disabled)return;
  const reason=$("rejection-reason").value.trim();if(reason.length<10||reason.length>2000){message("Enter a reason of 10 to 2000 characters.");return;}
  const body=action==="reject"?{completionId:completion.completionId,manifestDigest:completion.manifestDigest,version:completion.version,reason}:{caseId:crypto.randomUUID(),severity:$("severity").value,manifestDigest:completion.manifestDigest,version:completion.version,reason};
  busy=true;controls();
  try{const r=await post("/tenants/"+scope.t+"/milestones/"+scope.m+"/"+action,body);message(r.code===200&&r.data?.moneyMoved===false?(action==="reject"?"Work rejected. Fresh evidence and approval are required.":"Dispute opened. Ordinary payments are blocked. Case "+r.data.caseId):"Action not confirmed. Reload milestone.");}
  catch{message("Outcome uncertain. Reload the milestone before continuing.");}finally{clearView();busy=false;controls();}
 });
 $("reserve").addEventListener("click",async()=>{
  if(busy||!scope||!view||$("reserve").disabled)return;
  const pin=$("pin").value;$("pin").value="";
  if(!/^[0-9]{6}$/.test(pin)){message("Enter a six-digit PIN.");return;}
  if(BigInt(view.amountCents)>BigInt(Number.MAX_SAFE_INTEGER)){message("Amount exceeds supported limits.");return;}
  const current=scope,expected=Number(view.amountCents);attemptKey=attemptKey??crypto.randomUUID();
  busy=true;controls();
  try{const r=await post("/tenants/"+current.t+"/milestones/"+current.m+"/reserve",{pin,expectedAmountCents:expected,idempotencyKey:attemptKey});
   if(r.code===202&&r.data?.mode==="sandbox"&&r.data.moneyMoved===false&&r.data.status==="reserved"&&r.data.milestoneId===current.m&&r.data.amountCents===String(expected)){message("Authorisation reserved in sandbox. No money moved. Reload the milestone for its current status.");}
   else message("Authorisation not confirmed. Reload the milestone before taking any further action.");
  }catch{message("Outcome uncertain. Reload the milestone to reconcile; do not retry blindly.");}
  finally{clearView();busy=false;controls();}
 });
 $("grant").addEventListener("click",async()=>{
  if(busy||!scope)return;const stepUpToken=$("step-up").value.trim(),purpose=$("purpose").value;$("step-up").value="";grant=null;
  if(!stepUpToken){message("A separate recent MFA step-up token is required.");return;}
  busy=true;controls();try{const r=await post("/tenants/"+scope.t+"/pin/grant",{purpose,stepUpToken});
   if(r.code===201&&r.data?.mode==="sandbox"&&r.data.status==="grant_issued"&&uuid.test(r.data.grantRef)){grant={ref:r.data.grantRef,purpose};message("Short-lived PIN grant issued. Enter a new PIN.");}else message("PIN grant unavailable or denied.");
  }catch{message("Grant outcome uncertain. Obtain a fresh step-up token.");}finally{busy=false;controls();}
 });
 $("set-pin").addEventListener("click",async()=>{
  if(busy||!scope||!grant){message("Load a milestone and obtain a PIN grant first.");return;}
  const pin=$("new-pin").value;$("new-pin").value="";if(!/^[0-9]{6}$/.test(pin)){message("Enter a six-digit PIN.");return;}
  const g=grant;grant=null;busy=true;controls();
  try{const r=await post("/tenants/"+scope.t+"/pin",{pin,purpose:g.purpose,grantRef:g.ref});message(r.code===200&&r.data?.status==="pin_updated"?"PIN updated. Obtain fresh authentication if required.":"PIN update not confirmed. Reauthenticate before continuing.");}catch{message("PIN update outcome uncertain. Reauthenticate before continuing.");}
  finally{token="";clearView();busy=false;controls();}
 });
 $("clear").addEventListener("click",()=>{if(busy)return;token="";clearView();for(const id of ["token","step-up","new-pin","tenant","milestone"])$(id).value="";message("Session cleared.");});
 controls();
})();
`;
export function customerPortalPage(){
 return page("SecurePay customer portal",'<h1>SecurePay customer portal</h1><p class="notice">SANDBOX ONLY. No money moves. Use test credentials only.</p><section><h2>Access your milestone</h2><label for="tenant">Tenant reference</label><input id="tenant" autocomplete="off"><label for="milestone">Milestone reference</label><input id="milestone" autocomplete="off"><label for="token">Sandbox MFA access token</label><input id="token" type="password" autocomplete="off"><button id="load">Load milestone</button><button id="clear">Clear session</button></section><section id="details" hidden><h2>Payment details</h2><p>Loaded milestone: <span id="loaded-ref"></span></p><p class="amount" id="amount"></p><dl><dt>Milestone status</dt><dd id="state"></dd><dt>Funding status</dt><dd id="funding"></dd><dt>Release request</dt><dd id="request"></dd></dl><h3>Completion evidence</h3><button id="load-evidence">Load completion photos</button><p id="work-comments"></p><div id="evidence"></div><label><input type="checkbox" id="inspect"> I have inspected the submitted photos and accept the completed work.</label><button id="approve-work" disabled>Approve completed work</button><label for="rejection-reason">Reason for rejection or dispute</label><textarea id="rejection-reason" maxlength="2000" rows="3"></textarea><button id="reject-work" disabled>Request correction</button><label for="severity">Dispute severity</label><select id="severity"><option value="minor">Minor</option><option value="moderate">Moderate</option><option value="serious">Serious</option></select><button id="open-dispute" disabled>Open formal dispute</button><p>Only authorise after inspecting the completed work and confirming the amount. Disputed or unfunded work cannot be released.</p><label><input type="checkbox" id="confirm"> I have reviewed the work and exact amount displayed.</label><label for="pin">SecurePay PIN</label><input id="pin" type="password" inputmode="numeric" maxlength="6" autocomplete="off"><button id="reserve" disabled>Authorise sandbox release</button><h3>Set or recover PIN</h3><label for="purpose">Purpose</label><select id="purpose"><option value="enroll">Enrol PIN</option><option value="recover">Recover PIN</option></select><label for="step-up">Separate MFA step-up token</label><input id="step-up" type="password" autocomplete="off"><button id="grant">Request grant</button><label for="new-pin">New PIN</label><input id="new-pin" type="password" maxlength="6" inputmode="numeric" autocomplete="off"><button id="set-pin">Set PIN</button></section><p role="status" aria-live="polite" id="message"></p>',portalScript);
}
export function sendPortalPage(res,document){
 return res.set({"Cache-Control":"no-store","Content-Security-Policy":document.csp,"X-Content-Type-Options":"nosniff","Referrer-Policy":"no-referrer","X-Frame-Options":"DENY"}).type("html").send(document.html);
}

const ownerScript=String.raw`
(()=>{
 const $=id=>document.getElementById(id);let busy=false;
 const message=s=>$("message").textContent=s;
 const currency=value=>{const n=BigInt(value),a=n<0n?-n:n;return (n<0n?"-":"")+"AUD $"+String(a/100n)+"."+String(a%100n).padStart(2,"0");};
 function clear(){ $("summary").replaceChildren();$("rows").replaceChildren();$("report").hidden=true;}
 function metric(label,value){const d=document.createElement("dt"),v=document.createElement("dd");d.textContent=label;v.textContent=String(value);$("summary").append(d,v);}
 $("load").addEventListener("click",async()=>{
  if(busy)return;const token=$("token").value.trim();$("token").value="";clear();if(!token){message("Enter a sandbox owner MFA token.");return;}
  busy=true;$("load").disabled=true;
  try{
   const r=await fetch("/v1/securepay-owner/report",{method:"POST",headers:{"Content-Type":"application/json","Authorization":"Bearer "+token},body:"{}",cache:"no-store",credentials:"omit",redirect:"error"});
   if(!r.ok)throw Error("Report unavailable");
   const x=await r.json();
   if(x.report?.mode!=="sandbox"||x.report.moneyMoved!==false||!x.summary||!Array.isArray(x.report.milestones))throw Error("Invalid report");
   for(const [label,key] of [["Confirmed funding","fundedCents"],["Confirmed payouts","payoutCents"],["Confirmed refunds","refundCents"],["Remaining","remainingCents"]])metric(label,currency(x.summary[key]));
   for(const [label,key] of [["Journal mismatches","mismatches"],["Unresolved issues","unresolvedIssues"],["Uncertain legs","uncertainLegs"],["Disputed milestones","disputedMilestones"]])metric(label,x.summary[key]);
   for(const m of x.report.milestones){const tr=document.createElement("tr");for(const v of [m.milestoneId,m.status,m.fundingStatus,currency(m.remainingCents),m.journalVerified?"Matched":"Mismatch",m.unresolvedIssues]){const td=document.createElement("td");td.textContent=String(v);tr.append(td);}$("rows").append(tr);}
   $("report").hidden=false;message("Snapshot generated "+x.report.generatedAt+". No money moved.");
  }catch{clear();message("Report unavailable or access denied.");}finally{busy=false;$("load").disabled=false;}
 });
 $("clear").addEventListener("click",()=>{if(!busy){$("token").value="";clear();message("Report cleared.");}});
})();
`;
export function ownerDashboardPage(){
 return page("SecurePay owner dashboard",'<h1>SecurePay business-owner dashboard</h1><p class="notice">SANDBOX ONLY — read-only financial reconciliation. No real money moved.</p><section><label for="token">Sandbox owner MFA access token</label><input type="password" id="token" autocomplete="off"><button id="load">Load report</button><button id="clear">Clear report</button></section><section id="report" hidden><h2>Financial snapshot</h2><dl id="summary"></dl><h2>Milestones</h2><div style="overflow:auto"><table><thead><tr><th>Milestone</th><th>Status</th><th>Funding</th><th>Remaining</th><th>Journal</th><th>Issues</th></tr></thead><tbody id="rows"></tbody></table></div></section><p id="message" role="status" aria-live="polite"></p>',ownerScript);
}

const completionOwnerScript="\n(()=>{\n const $=id=>document.getElementById(id),uuid=/^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$/;\n let token=\"\",scope=null,completion=null,busy=false;\n const message=s=>$(\"message\").textContent=s;\n function clear(){scope=null;completion=null;$(\"details\").hidden=true;$(\"history\").replaceChildren();$(\"notes\").value=\"\";$(\"file\").value=\"\";}\n function controls(){for(const id of [\"load\",\"clear\",\"milestone\",\"token\",\"file\",\"notes\"])$(id).disabled=busy;$(\"start\").disabled=busy||!scope||scope.status!==\"planned\"||!!completion;$(\"upload\").disabled=busy||!completion||completion.status!==\"draft\";$(\"submit\").disabled=busy||!completion||completion.status!==\"draft\"||completion.photoCount<1;}\n async function post(action,milestoneId,body){const r=await fetch(\"/v1/securepay-completion/\"+milestoneId+\"/\"+action,{method:\"POST\",headers:{\"Content-Type\":\"application/json\",Authorization:\"Bearer \"+token},body:JSON.stringify(body),cache:\"no-store\",credentials:\"omit\",redirect:\"error\"});if(!r.ok)throw Error(\"Action denied\");const result=await r.json();if(result.mode!==\"sandbox\"||result.moneyMoved!==false)throw Error(\"Invalid response\");return result;}\n async function refresh(id){const r=await post(\"status\",id,{});if(r.view?.milestoneId!==id)throw Error(\"Invalid milestone\");scope=r.view;completion=r.view.current;$(\"scope\").textContent=id;$(\"state\").textContent=scope.status;$(\"count\").textContent=String(completion?.photoCount??0);$(\"history\").replaceChildren();for(const item of scope.rejections){const p=document.createElement(\"p\");p.textContent=item.reason;$(\"history\").append(p);}$(\"details\").hidden=false;}\n for(const id of [\"token\",\"milestone\"])$(id).addEventListener(\"input\",()=>{if(!busy){if(id===\"token\")token=\"\";clear();controls();}});\n $(\"load\").addEventListener(\"click\",async()=>{if(busy)return;const id=$(\"milestone\").value.trim(),supplied=$(\"token\").value.trim();$(\"token\").value=\"\";if(supplied)token=supplied;clear();if(!uuid.test(id)||!token){message(\"Enter milestone and test MFA token.\");return;}busy=true;controls();try{await refresh(id);message(\"Work completion status loaded.\");}catch{clear();message(\"Access denied or status unavailable.\");}finally{busy=false;controls();}});\n for(const action of [\"start\",\"upload\",\"submit\"])$(action).addEventListener(\"click\",async()=>{\n  if(busy||!scope||$(action).disabled)return;const id=scope.milestoneId;busy=true;controls();\n  try{\n   let body={};\n   if(action===\"upload\"){\n    const file=$(\"file\").files[0];if(!file||![\"image/jpeg\",\"image/png\"].includes(file.type)||file.size<8||file.size>2097152)throw Error(\"Select a PNG or JPEG up to 2 MiB.\");\n    const bytes=new Uint8Array(await file.arrayBuffer());let raw=\"\";for(let i=0;i<bytes.length;i+=8192)raw+=String.fromCharCode(...bytes.subarray(i,i+8192));\n    body={completionId:completion.completionId,mediaType:file.type,content:btoa(raw)};\n   }else if(action===\"submit\")body={completionId:completion.completionId,comments:$(\"notes\").value};\n   await post(action,id,body);$(\"file\").value=\"\";await refresh(id);message(action===\"submit\"?\"Submitted for customer inspection. No payment authorised.\":\"Completion updated.\");\n  }catch{clear();message(\"Action not confirmed. Reload before attempting again.\");}finally{busy=false;controls();}\n });\n $(\"clear\").addEventListener(\"click\",()=>{if(!busy){clear();token=\"\";$(\"token\").value=\"\";$(\"milestone\").value=\"\";message(\"Session cleared.\");controls();}});\n controls();\n})();\n";
export function ownerCompletionPage(){return page("SecurePay work completion",'<h1>SecurePay work completion</h1><p class="notice">SANDBOX ONLY. Use synthetic photos and test credentials.</p><section><label for="milestone">Milestone reference</label><input id="milestone" autocomplete="off"><label for="token">Completion MFA access token</label><input id="token" type="password" autocomplete="off"><button id="load">Load milestone</button><button id="clear">Clear session</button></section><section id="details" hidden><h2>Assigned work</h2><p id="scope"></p><p id="state"></p><h3>Customer correction requests</h3><div id="history"></div><button id="start" disabled>Start new submission</button><label for="file">Completion photograph (PNG or JPEG, up to 2 MiB)</label><input id="file" type="file" accept="image/png,image/jpeg"><button id="upload" disabled>Screen and upload photo</button><p>Photos accepted: <span id="count">0</span></p><label for="notes">Optional completion comments</label><textarea id="notes" maxlength="2000" rows="3"></textarea><button id="submit" disabled>Submit for customer inspection</button></section><p id="message" role="status" aria-live="polite"></p>',completionOwnerScript);}

export function customerQuotePage(){return page("SecurePay quote agreement","<h1>SecurePay quote agreement</h1><p class=\"notice\">SANDBOX ONLY. No money moves.</p><section><label for=\"tenant\">Tenant reference</label><input id=\"tenant\"><label for=\"plan\">Payment plan reference</label><input id=\"plan\"><label for=\"token\">Sandbox MFA token</label><input id=\"token\" type=\"password\" autocomplete=\"off\"><button id=\"load\">Load agreement</button><button id=\"clear\">Clear session</button></section><section id=\"details\" hidden><p id=\"reference\"></p><p>Quote revision <span id=\"revision\"></span> · <span id=\"state\"></span></p><h2>Agreed work</h2><p id=\"description\"></p><p class=\"amount\" id=\"total\"></p><h2>Payment milestones</h2><ol id=\"stages\"></ol><label><input type=\"checkbox\" id=\"agree\"> I agree to the exact work scope, price and milestone amounts displayed.</label><button id=\"accept\" disabled>Accept agreement</button><p>Acceptance does not authorise a payment.</p></section><p id=\"message\" role=\"status\" aria-live=\"polite\"></p>","(()=>{\n const $=id=>document.getElementById(id),uuid=/^[a-f0-9-]{36}$/;let plan=null,scope=null,token=\"\",busy=false;\n const message=s=>$(\"message\").textContent=s;\n const money=x=>{const n=BigInt(x);return \"AUD $\"+String(n/100n)+\".\"+String(n%100n).padStart(2,\"0\");};\n function clear(){plan=null;scope=null;$(\"agree\").checked=false;$(\"details\").hidden=true;$(\"stages\").replaceChildren();$(\"description\").textContent=\"\";}\n function controls(){for(const id of [\"load\",\"clear\",\"tenant\",\"plan\",\"token\",\"agree\"])$(id).disabled=busy;$(\"accept\").disabled=busy||!plan||plan.status!==\"offered\"||!$(\"agree\").checked;}\n async function post(t,p,action,body){const r=await fetch(\"/v1/securepay/tenants/\"+t+\"/plans/\"+p+\"/\"+action,{method:\"POST\",headers:{\"Content-Type\":\"application/json\",Authorization:\"Bearer \"+token},body:JSON.stringify(body),credentials:\"omit\",cache:\"no-store\",redirect:\"error\"});if(!r.ok)throw Error(\"Unavailable\");const x=await r.json();if(x.mode!==\"sandbox\"||x.moneyMoved!==false||x.planId!==p)throw Error(\"Invalid response\");return x;}\n for(const id of [\"tenant\",\"plan\",\"token\"])$(id).addEventListener(\"input\",()=>{if(!busy){if(id===\"token\")token=\"\";clear();controls();}});\n $(\"agree\").addEventListener(\"change\",controls);\n $(\"load\").addEventListener(\"click\",async()=>{if(busy)return;const t=$(\"tenant\").value.trim(),p=$(\"plan\").value.trim(),supplied=$(\"token\").value.trim();$(\"token\").value=\"\";if(supplied)token=supplied;clear();if(!uuid.test(t)||!uuid.test(p)||!token){message(\"Enter the references and sandbox MFA token.\");return;}busy=true;controls();try{\n  const x=await post(t,p,\"view\",{});if(!x.quote||typeof x.quote.description!==\"string\"||!Array.isArray(x.items)||x.items.length<1||x.items.length>20||x.quote.totalCents!==x.totalCents||!/^[1-9][0-9]{0,15}$/.test(x.totalCents)||BigInt(x.totalCents)>BigInt(Number.MAX_SAFE_INTEGER)||x.items.reduce((n,i)=>n+BigInt(i.amountCents),0n)!==BigInt(x.totalCents)||!/^[a-f0-9]{64}$/.test(x.planDigest))throw Error(\"Invalid quote\");\n  $(\"description\").textContent=x.quote.description;$(\"revision\").textContent=String(x.quote.revision);$(\"total\").textContent=money(x.totalCents);$(\"state\").textContent=x.status;$(\"reference\").textContent=p;\n  for(const i of x.items){const li=document.createElement(\"li\");li.textContent=i.description+\" — \"+money(i.amountCents)+(i.final?\" (final)\":\"\")+\" — \"+i.milestoneId;$(\"stages\").append(li);}\n  plan=x;scope={t,p};$(\"details\").hidden=false;message(\"Review the exact scope and payment stages.\");\n }catch{clear();message(\"Quote unavailable or access denied.\");}finally{busy=false;controls();}});\n $(\"accept\").addEventListener(\"click\",async()=>{if(busy||!scope||!plan||$(\"accept\").disabled)return;busy=true;controls();try{const x=await post(scope.t,scope.p,\"accept\",{planDigest:plan.planDigest,expectedTotalCents:Number(plan.totalCents)});if(x.status!==\"plan_accepted\")throw Error(\"Invalid response\");message(\"Agreement accepted. Reload to view your milestone references. No payment was made.\");}catch{message(\"Acceptance not confirmed. Reload the agreement before taking further action.\");}finally{clear();busy=false;controls();}});\n $(\"clear\").addEventListener(\"click\",()=>{if(!busy){token=\"\";clear();for(const id of [\"tenant\",\"plan\",\"token\"])$(id).value=\"\";message(\"Session cleared.\");controls();}});controls();\n})();");}
export function ownerQuotePage(){return page("SecurePay quotation manager","<h1>SecurePay quotation manager</h1><p class=\"notice\">SANDBOX ONLY. Use synthetic job and customer data.</p><section><label for=\"job\">Assigned job reference</label><input id=\"job\"><label for=\"token\">Completion MFA token</label><input id=\"token\" type=\"password\" autocomplete=\"off\"><button id=\"load\">Load quote</button><button id=\"clear\">Clear session</button></section><section id=\"details\" hidden><p id=\"reference\"></p><p>Current revision <span id=\"revision\"></span></p><label for=\"description\">Customer-facing scope of work</label><textarea id=\"description\" maxlength=\"4000\" rows=\"5\"></textarea><label for=\"total\">Total AUD (inclusive agreed price)</label><input id=\"total\" inputmode=\"decimal\"><button id=\"publish\">Publish quote revision</button><p>Publishing withdraws unaccepted offers. Accepted quotes cannot be amended here.</p><h2>Payment stages</h2><p>Current offer: <span id=\"plan-ref\"></span></p><label for=\"stage-description\">Stage description</label><input id=\"stage-description\" maxlength=\"500\"><label for=\"stage-amount\">Stage amount AUD</label><input id=\"stage-amount\" inputmode=\"decimal\"><button id=\"add\">Add stage</button><button id=\"reset\">Clear stages</button><ol id=\"stages\"></ol><button id=\"offer\">Offer exact payment plan</button><button id=\"withdraw\">Withdraw unaccepted offer</button><p>The last stage is always the final stage. For a single payment, add one stage for the full total.</p></section><p id=\"message\" role=\"status\" aria-live=\"polite\"></p>","(()=>{\n const $=id=>document.getElementById(id),uuid=/^[a-f0-9-]{36}$/;let job=null,view=null,token=\"\",busy=false,stages=[];\n const message=s=>$(\"message\").textContent=s;\n const money=s=>{if(!/^[0-9]{1,13}(?:\\.[0-9]{1,2})?$/.test(s))throw Error(\"Enter an AUD amount with at most two decimal places.\");const [d,c=\"\"]=s.split(\".\"),n=BigInt(d)*100n+BigInt(c.padEnd(2,\"0\"));if(n<=0n||n>BigInt(Number.MAX_SAFE_INTEGER))throw Error(\"Invalid amount\");return Number(n);};\n function clear(){job=null;view=null;stages=[];$(\"details\").hidden=true;$(\"stages\").replaceChildren();$(\"description\").value=\"\";$(\"total\").value=\"\";$(\"stage-description\").value=\"\";$(\"stage-amount\").value=\"\";}\n function render(){ $(\"stages\").replaceChildren();for(const x of stages){const li=document.createElement(\"li\");li.textContent=x.description+\" — \"+x.amountCents+\" cents\";$(\"stages\").append(li);} }\n function controls(){for(const id of [\"load\",\"clear\",\"job\",\"token\",\"description\",\"total\",\"stage-description\",\"stage-amount\"])$(id).disabled=busy;const locked=view?.plan?.status===\"accepted\";$(\"publish\").disabled=busy||!job||locked;$(\"add\").disabled=busy||!job||!view?.quote||!!view.plan||stages.length>=20;$(\"reset\").disabled=busy||!job;$(\"offer\").disabled=busy||!job||!view?.quote||!!view.plan||stages.length===0;$(\"withdraw\").disabled=busy||view?.plan?.status!==\"offered\";}\n async function post(id,action,body){const r=await fetch(\"/v1/securepay-completion/\"+id+\"/\"+action,{method:\"POST\",headers:{\"Content-Type\":\"application/json\",Authorization:\"Bearer \"+token},body:JSON.stringify(body),cache:\"no-store\",credentials:\"omit\",redirect:\"error\"});if(!r.ok)throw Error(\"Action denied\");const x=await r.json();if(x.mode!==\"sandbox\"||x.moneyMoved!==false)throw Error(\"Invalid response\");return x;}\n async function refresh(id){const x=await post(id,\"quote-status\",{});if(x.view?.jobId!==id)throw Error(\"Invalid scope\");job=id;view=x.view;stages=[];render();$(\"reference\").textContent=id;$(\"revision\").textContent=view.quote?String(view.quote.revision):\"None\";$(\"description\").value=view.quote?.description??\"\";$(\"total\").value=view.quote?String(BigInt(view.quote.totalCents)/100n)+\".\"+String(BigInt(view.quote.totalCents)%100n).padStart(2,\"0\"):\"\";$(\"plan-ref\").textContent=view.plan?view.plan.planId+\" — \"+view.plan.status:\"None\";$(\"details\").hidden=false;}\n for(const id of [\"job\",\"token\"])$(id).addEventListener(\"input\",()=>{if(!busy){if(id===\"token\")token=\"\";clear();controls();}});\n $(\"load\").addEventListener(\"click\",async()=>{if(busy)return;const id=$(\"job\").value.trim(),supplied=$(\"token\").value.trim();$(\"token\").value=\"\";if(supplied)token=supplied;clear();if(!uuid.test(id)||!token){message(\"Enter job reference and sandbox MFA token.\");return;}busy=true;controls();try{await refresh(id);message(\"Quote status loaded.\");}catch{clear();message(\"Quote unavailable or access denied.\");}finally{busy=false;controls();}});\n $(\"add\").addEventListener(\"click\",()=>{if($(\"add\").disabled)return;try{const d=$(\"stage-description\").value.trim();if(!d||d.length>500)throw Error(\"Enter stage description.\");stages.push({milestoneId:crypto.randomUUID(),description:d,amountCents:money($(\"stage-amount\").value.trim()),final:false});$(\"stage-description\").value=\"\";$(\"stage-amount\").value=\"\";render();controls();}catch(e){message(e.message);}});\n $(\"reset\").addEventListener(\"click\",()=>{if(!busy){stages=[];render();controls();}});\n for(const [id,action] of [[\"publish\",\"publish-quote\"],[\"offer\",\"offer-plan\"],[\"withdraw\",\"withdraw-plan\"]])$(id).addEventListener(\"click\",async()=>{if(busy||!job||$(id).disabled)return;let body;\n  try{if(action===\"publish-quote\"){const description=$(\"description\").value.trim();if(!description||description.length>4000)throw Error(\"Enter quote scope.\");body={previousDigest:view.quote?.quoteDigest??null,description,totalCents:money($(\"total\").value.trim())};}\n  else if(action===\"offer-plan\"){if(stages.reduce((n,i)=>n+BigInt(i.amountCents),0n)!==BigInt(view.quote.totalCents))throw Error(\"Stage amounts must equal the published quote.\");body={quoteDigest:view.quote.quoteDigest,items:stages.map((x,i)=>({...x,final:i===stages.length-1}))};}\n  else body={planId:view.plan.planId};}catch(e){message(e.message);return;}const current=job;busy=true;controls();try{await post(current,action,body);await refresh(current);message(action===\"offer-plan\"?\"Offer published. Share the plan reference with the intended customer through an approved channel.\":action===\"publish-quote\"?\"Quote revision published. Any previous unaccepted offer is withdrawn.\":\"Offer withdrawn.\");}catch{clear();message(\"Action not confirmed. Reload before trying again.\");}finally{busy=false;controls();}});\n $(\"clear\").addEventListener(\"click\",()=>{if(!busy){token=\"\";clear();$(\"job\").value=\"\";$(\"token\").value=\"\";message(\"Session cleared.\");controls();}});controls();\n})();");}

const contractScript="(()=>{\n const $=id=>document.getElementById(id),uuid=/^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$/;\n let scope=null,token=\"\",view=null,pending=null,busy=false;\n const message=s=>$(\"message\").textContent=s;\n const money=s=>{const n=BigInt(s);return \"AUD $\"+String(n/100n)+\".\"+String(n%100n).padStart(2,\"0\");};\n const cents=s=>{if(!/^[0-9]{1,13}(?:\\.[0-9]{1,2})?$/.test(s))throw Error(\"Enter an exact AUD amount.\");const [d,c=\"\"]=s.split(\".\"),n=BigInt(d)*100n+BigInt(c.padEnd(2,\"0\"));if(n<=0n||n>9007199254740991n)throw Error(\"Invalid amount\");return Number(n);};\n function clear(){scope=null;view=null;pending=null;$(\"details\").hidden=true;$(\"stages\").replaceChildren();$(\"changes\").replaceChildren();$(\"agree\").checked=false;$(\"reason\").value=\"\";$(\"new-description\").value=\"\";$(\"new-amount\").value=\"\";$(\"target\").value=\"\";}\n function controls(){\n  for(const id of [\"load\",\"clear\",\"tenant\",\"plan\",\"token\",\"target\",\"kind\",\"new-description\",\"new-amount\",\"reason\",\"agree\"])$(id).disabled=busy;\n  const eligible=view?.state.stages.some(x=>x.eligible)&&view.state.stages.every(x=>x.eligible||x.terminalVerified||x.status===\"cancelled\");\n  $(\"offer\").disabled=busy||!owner||!view||!!pending||!eligible||view.changes.length>=20;\n  $(\"withdraw\").disabled=busy||!owner||!pending;\n  $(\"accept\").disabled=busy||owner||!pending||!pending.current||!$(\"agree\").checked;\n }\n async function post(s,action,body){\n  const base=owner?\"/v1/securepay-completion/\"+s.p:\"/v1/securepay/tenants/\"+s.t+\"/plans/\"+s.p;\n  const r=await fetch(base+\"/\"+action,{method:\"POST\",headers:{\"Content-Type\":\"application/json\",\"Authorization\":\"Bearer \"+token},body:JSON.stringify(body),credentials:\"omit\",cache:\"no-store\",redirect:\"error\"});\n  if(!r.ok)throw Error(\"Action denied\");const x=await r.json();if(x.mode!==\"sandbox\"||x.moneyMoved!==false)throw Error(\"Invalid response\");return x;\n }\n const line=(parent,value)=>{const e=document.createElement(\"li\");e.textContent=value;parent.append(e);};\n async function refresh(s){\n  const x=await post(s,owner?\"contract-status\":\"contract\",{}),c=x.contract;\n  if(c?.state?.planId!==s.p||!Array.isArray(c.state.stages)||!Array.isArray(c.changes)||!/^[a-f0-9]{64}$/.test(c.stateDigest))throw Error(\"Invalid contract\");\n  scope=s;view=c;pending=c.changes.find(x=>x.status===\"offered\")??null;$(\"agree\").checked=false;\n  $(\"original\").textContent=money(c.state.originalTotalCents);$(\"effective\").textContent=money(c.state.effectiveTotalCents);\n  $(\"ref\").textContent=s.p;$(\"stages\").replaceChildren();$(\"changes\").replaceChildren();\n  for(const x of c.state.stages)line($(\"stages\"),x.description+\" — \"+money(x.amountCents)+\" — \"+x.status+\" — \"+x.milestoneId+(x.eligible?\" (eligible)\":\"\"));\n  for(const x of c.changes){\n   line($(\"changes\"),x.kind+\" — \"+x.status+(x.status===\"offered\"&&!x.current?\" (stale; withdraw and re-offer)\":\"\")+\" — \"+money(x.oldTotalCents)+\" → \"+money(x.newTotalCents)+\" — \"+x.reason);\n   for(const a of x.affectedStages)line($(\"changes\"),\"Affected: \"+a.description+\" — \"+money(a.amountCents)+\" — \"+a.milestoneId);\n   if(x.kind===\"variation\")line($(\"changes\"),\"New scope: \"+x.newDescription+\" — \"+money(x.newAmountCents));\n  }\n  $(\"details\").hidden=false;\n }\n for(const id of [\"tenant\",\"plan\",\"token\"])$(id).addEventListener(\"input\",()=>{if(!busy){if(id===\"token\")token=\"\";clear();controls();}});\n $(\"load\").addEventListener(\"click\",async()=>{if(busy)return;const p=$(\"plan\").value.trim(),t=$(\"tenant\").value.trim(),supplied=$(\"token\").value.trim();$(\"token\").value=\"\";if(supplied)token=supplied;clear();if(!uuid.test(p)||(!owner&&!uuid.test(t))||!token){message(\"Enter references and test MFA token.\");return;}busy=true;controls();try{await refresh({p,t});message(\"Review the current agreement and change history.\");}catch{clear();message(\"Contract unavailable or access denied.\");}finally{busy=false;controls();}});\n $(\"agree\").addEventListener(\"change\",controls);\n for(const [id,action] of [[\"offer\",\"offer-change\"],[\"withdraw\",\"withdraw-change\"],[\"accept\",\"accept-change\"]])$(id).addEventListener(\"click\",async()=>{\n  if(busy||!scope||$(id).disabled)return;let body;\n  try{\n   if(id===\"offer\"){const kind=$(\"kind\").value,reason=$(\"reason\").value.trim();if(reason.length<10||reason.length>2000)throw Error(\"Enter a clear reason.\");body={kind,reason,stateDigest:view.stateDigest,milestoneId:null,newAmountCents:null,newDescription:null};\n    if(kind===\"variation\"){const target=$(\"target\").value.trim(),desc=$(\"new-description\").value.trim();if(!view.state.stages.some(x=>x.eligible&&x.milestoneId===target)||!desc||desc.length>500)throw Error(\"Choose an eligible milestone and new scope.\");body.milestoneId=target;body.newAmountCents=cents($(\"new-amount\").value.trim());body.newDescription=desc;}\n   }else if(id===\"withdraw\")body={changeId:pending.changeId};\n   else body={changeId:pending.changeId,changeDigest:pending.changeDigest,expectedTotalCents:Number(pending.newTotalCents)};\n  }catch(e){message(e.message);return;}\n  const s=scope;busy=true;controls();try{await post(s,action,body);await refresh(s);message(id===\"accept\"?\"Change accepted. No payment moved.\":id===\"offer\"?\"Proposal recorded. Customer acceptance required.\":\"Proposal withdrawn.\");}catch{clear();message(\"Action not confirmed. Reload before continuing.\");}finally{busy=false;controls();}\n });\n $(\"clear\").addEventListener(\"click\",()=>{if(!busy){token=\"\";clear();for(const id of [\"tenant\",\"plan\",\"token\"])$(id).value=\"\";message(\"Session cleared.\");controls();}});controls();\n})();";
const contractMarkup="<h1>SecurePay contract changes</h1><p class=\"notice\">SANDBOX ONLY. Changes affect untouched, unfunded work only. No payment moves. Funded or started work needs separate resolution.</p><section><label for=\"tenant\">Tenant reference (customer only)</label><input id=\"tenant\"><label for=\"plan\">Accepted payment plan reference</label><input id=\"plan\"><label for=\"token\">Sandbox MFA token</label><input id=\"token\" type=\"password\" autocomplete=\"off\"><button id=\"load\">Load contract</button><button id=\"clear\">Clear session</button></section><section id=\"details\" hidden><p id=\"ref\"></p><p>Original total: <span id=\"original\"></span></p><p>Effective total: <span id=\"effective\"></span></p><h2>Current stages</h2><ol id=\"stages\"></ol><h2>Change proposals and history</h2><ul id=\"changes\"></ul><div OWNER><h3>Propose a change</h3><label for=\"kind\">Change type</label><select id=\"kind\"><option value=\"variation\">Variation of one eligible milestone</option><option value=\"cancel_remaining\">Cancel all remaining untouched stages</option></select><label for=\"target\">Eligible milestone reference (variation only)</label><input id=\"target\"><label for=\"new-description\">Revised scope (variation only)</label><textarea id=\"new-description\" maxlength=\"500\"></textarea><label for=\"new-amount\">New amount AUD (variation only)</label><input id=\"new-amount\" inputmode=\"decimal\"><label for=\"reason\">Reason</label><textarea id=\"reason\" maxlength=\"2000\"></textarea><button id=\"offer\" disabled>Offer change</button><button id=\"withdraw\" disabled>Withdraw proposal</button></div><div CUSTOMER><label><input type=\"checkbox\" id=\"agree\"> I agree to the exact current change, affected stages and revised total above.</label><button id=\"accept\" disabled>Accept change</button></div></section><p id=\"message\" role=\"status\" aria-live=\"polite\"></p>";
export function customerContractPage(){return page("SecurePay contract change agreement",contractMarkup.replace("OWNER","hidden").replace("CUSTOMER",""),"const owner=false;"+contractScript);}
