const cancellationScript="(()=>{\nconst $=id=>document.getElementById(id),id=/^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$/;let token=\"\",scope=null,view=null,busy=false;\nconst msg=s=>$(\"message\").textContent=s,money=s=>{const n=BigInt(s);return \"AUD $\"+String(n/100n)+\".\"+String(n%100n).padStart(2,\"0\");};\nfunction cents(s){if(!/^[0-9]{1,13}(?:\\.[0-9]{1,2})?$/.test(s))throw Error(\"Enter exact AUD amounts.\");const [d,c=\"\"]=s.split(\".\"),n=BigInt(d)*100n+BigInt(c.padEnd(2,\"0\"));if(n>9007199254740991n)throw Error(\"Amount exceeds limit\");return Number(n);}\nfunction clear(){scope=null;view=null;$(\"details\").hidden=true;$(\"stages\").replaceChildren();$(\"offers\").replaceChildren();$(\"agree\").checked=false;for(const k of [\"target\",\"payout\",\"refund\",\"reason\",\"offer-ref\",\"appeal-reason\"])$(k).value=\"\";}\nfunction selected(){return view?.offers.find(o=>o.offerId===$(\"offer-ref\").value.trim());}\nfunction controls(){for(const k of [\"load\",\"clear\",\"tenant\",\"plan\",\"token\",\"target\",\"payout\",\"refund\",\"reason\",\"offer-ref\",\"agree\",\"appeal-reason\"])$(k).disabled=busy;const o=selected(),decided=o?.status===\"accepted\"&&o.caseStatus===\"decided\"&&o.decision;\n$(\"offer\").disabled=busy||!owner||!view||view.offers.length>=20||!view.stages.some(s=>s.stateDigest);\n$(\"withdraw\").disabled=busy||!owner||o?.status!==\"offered\";$(\"accept\").disabled=busy||owner||!o?.current||!$(\"agree\").checked;\n$(\"ack\").disabled=busy||!decided||!$(\"agree\").checked||(owner?o.ownerAcknowledged:o.customerAcknowledged);\n$(\"appeal\").disabled=busy||owner||!decided;}\nasync function post(s,action,body){const base=owner?\"/v1/securepay-completion/\"+s.p:\"/v1/securepay/tenants/\"+s.t+\"/plans/\"+s.p;const r=await fetch(base+\"/\"+action,{method:\"POST\",headers:{\"Content-Type\":\"application/json\",\"Authorization\":\"Bearer \"+token},body:JSON.stringify(body),credentials:\"omit\",cache:\"no-store\",redirect:\"error\"});if(!r.ok)throw Error(\"Action denied\");const x=await r.json();if(x.mode!==\"sandbox\"||x.moneyMoved!==false)throw Error(\"Invalid response\");return x;}\nfunction line(parent,s){const e=document.createElement(\"li\");e.textContent=s;parent.append(e);}\nasync function refresh(s){const x=await post(s,owner?\"funded-cancellation-status\":\"funded-cancellation\",{}),v=x.cancellation;if(v?.planId!==s.p||!Array.isArray(v.stages)||!Array.isArray(v.offers))throw Error(\"Invalid cancellation view\");view=v;scope=s;$(\"agree\").checked=false;$(\"offer-ref\").value=\"\";$(\"stages\").replaceChildren();$(\"offers\").replaceChildren();for(const m of v.stages)line($(\"stages\"),m.description+\" — \"+money(m.amountCents)+\" — \"+m.status+\" — \"+m.milestoneId+(m.stateDigest?\" (eligible for negotiated cancellation)\":\"\"));\nfor(const o of v.offers){line($(\"offers\"),o.offerId+\" — \"+o.status+(o.current?\" (current)\":\"\")+\" — proposed business payout \"+money(o.payoutCents)+\", customer refund \"+money(o.refundCents)+\" — \"+o.reason);if(o.caseId)line($(\"offers\"),\"Case \"+o.caseId+\" — \"+o.caseStatus+\" — confirmed payout \"+money(o.confirmedPayoutCents)+\", confirmed refund \"+money(o.confirmedRefundCents)+\", remaining \"+money(o.remainingCents));if(o.decision)line($(\"offers\"),\"Independent decision: \"+o.decision.reason+\" — payout \"+money(o.decisionPayoutCents)+\", refund \"+money(o.decisionRefundCents)+\" — customer acknowledgement \"+o.customerAcknowledged+\", owner acknowledgement \"+o.ownerAcknowledged);}\n$(\"confirmed\").textContent=money(v.confirmedCancellationRefundCents);$(\"details\").hidden=false;}\nfor(const k of [\"tenant\",\"plan\",\"token\"])$(k).addEventListener(\"input\",()=>{if(!busy){if(k===\"token\")token=\"\";clear();controls();}});\n$(\"offer-ref\").addEventListener(\"input\",()=>{$(\"agree\").checked=false;controls();});$(\"agree\").addEventListener(\"change\",controls);\n$(\"load\").addEventListener(\"click\",async()=>{if(busy)return;const p=$(\"plan\").value.trim(),t=$(\"tenant\").value.trim(),supplied=$(\"token\").value.trim();$(\"token\").value=\"\";if(supplied)token=supplied;clear();if(!id.test(p)||(!owner&&!id.test(t))||!token){msg(\"Enter references and test MFA token.\");return;}busy=true;controls();try{await refresh({p,t});msg(\"Review proposals and actual confirmed balances separately.\");}catch{clear();msg(\"Cancellation view unavailable.\");}finally{busy=false;controls();}});\nfor(const [k,action] of [[\"offer\",\"offer-funded-cancellation\"],[\"withdraw\",\"withdraw-funded-cancellation\"],[\"accept\",\"accept-funded-cancellation\"],[\"ack\",\"ack-negotiated\"],[\"appeal\",\"appeal-negotiated\"]])$(k).addEventListener(\"click\",async()=>{\n if(busy||!scope||$(k).disabled)return;let body;const o=selected(),s=scope;busy=true;controls();try{\n if(k===\"offer\"){const m=view.stages.find(x=>x.milestoneId===$(\"target\").value.trim()),payoutCents=cents($(\"payout\").value.trim()),refundCents=cents($(\"refund\").value.trim()),reason=$(\"reason\").value.trim();if(!m?.stateDigest||refundCents<=0||BigInt(payoutCents)+BigInt(refundCents)!==BigInt(m.amountCents)||reason.length<10||reason.length>2000)throw Error(\"Choose eligible work and an exact split with a reason.\");body={milestoneId:m.milestoneId,payoutCents,refundCents,reason,stateDigest:m.stateDigest};}\n else if(k===\"withdraw\")body={offerId:o.offerId};\n else if(k===\"accept\")body={offerId:o.offerId,offerDigest:o.offerDigest,payoutCents:Number(o.payoutCents),refundCents:Number(o.refundCents)};\n else if(k===\"ack\")body={offerId:o.offerId,decisionId:o.decision.eventId,payoutCents:Number(o.decisionPayoutCents),refundCents:Number(o.decisionRefundCents)};\n else {const reason=$(\"appeal-reason\").value.trim();if(reason.length<10||reason.length>2000)throw Error(\"Enter an appeal reason.\");const digest=await crypto.subtle.digest(\"SHA-256\",new TextEncoder().encode(reason));body={offerId:o.offerId,decisionId:o.decision.eventId,reason,evidenceDigest:Array.from(new Uint8Array(digest),x=>x.toString(16).padStart(2,\"0\")).join(\"\")};}\n }catch(e){msg(e.message);busy=false;controls();return;}try{await post(s,action,body);await refresh(s);msg(k===\"accept\"?\"Negotiated case opened for independent review. No payment moved.\":\"Action recorded. No payment moved.\");}catch{clear();msg(\"Action not confirmed. Reload before proceeding.\");}finally{busy=false;controls();}\n});\n$(\"clear\").addEventListener(\"click\",()=>{if(!busy){token=\"\";clear();for(const k of [\"tenant\",\"plan\",\"token\"])$(k).value=\"\";msg(\"Session cleared.\");controls();}});controls();\n})();";
const cancellationMarkup="<h1>SecurePay funded cancellation</h1><p class=\"notice\">SANDBOX ONLY. A proposal is not a refund. Independent review and signed provider confirmations are mandatory.</p><section><label for=\"tenant\">Tenant reference (customer only)</label><input id=\"tenant\"><label for=\"plan\">Accepted plan reference</label><input id=\"plan\"><label for=\"token\">Test MFA token</label><input id=\"token\" type=\"password\" autocomplete=\"off\"><button id=\"load\">Load</button><button id=\"clear\">Clear session</button></section><section id=\"details\" hidden><h2>Stages</h2><ul id=\"stages\"></ul><h2>Negotiated offers and decisions</h2><ul id=\"offers\"></ul><p>Confirmed refunds on settled cancellation cases: <span id=\"confirmed\"></span></p><div OWNER><h2>Propose funded cancellation</h2><label for=\"target\">Eligible stage reference</label><input id=\"target\"><label for=\"payout\">Proposed business payout AUD</label><input id=\"payout\" inputmode=\"decimal\"><label for=\"refund\">Proposed customer refund AUD</label><input id=\"refund\" inputmode=\"decimal\"><label for=\"reason\">Reason</label><textarea id=\"reason\" maxlength=\"2000\"></textarea><button id=\"offer\" disabled>Propose split</button></div><label for=\"offer-ref\">Selected offer reference</label><input id=\"offer-ref\"><label><input id=\"agree\" type=\"checkbox\"> I accept the exact selected offer or provisional decision shown above.</label><button id=\"withdraw\" disabled OWNER>Withdraw offer</button><button id=\"accept\" disabled CUSTOMER>Accept proposal for independent review</button><button id=\"ack\" disabled>Acknowledge exact decision</button><div CUSTOMER><label for=\"appeal-reason\">Appeal reason (text evidence only)</label><textarea id=\"appeal-reason\" maxlength=\"2000\"></textarea><button id=\"appeal\" disabled>Appeal provisional decision</button></div></section><p id=\"message\" role=\"status\" aria-live=\"polite\"></p>";
