export function reviewerPage(){return page("SecurePay independent reviewer","<h1>SecurePay independent reviewer</h1><p class=\"notice\">SANDBOX ONLY. Assigned cases only. Decisions do not authorise or execute payments.</p><section><label for=\"token\">Reviewer MFA test token</label><input id=\"token\" type=\"password\" autocomplete=\"off\"><button id=\"load\">Load assigned queue</button><button id=\"clear\">Clear session</button><button id=\"assignments\">Show governance assignments</button><ol id=\"assignment-list\"></ol><label><input id=\"independent\" type=\"checkbox\"> No known personal, financial or professional conflict; I will disclose any change</label><button id=\"declare\">Declare independence for case reference below</button><h2>Assigned cases</h2><ol id=\"queue\"></ol><label for=\"case-ref\">Case reference</label><input id=\"case-ref\"><button id=\"open\">Open case</button></section><section id=\"details\" hidden><h2>Case overview</h2><p id=\"status\"></p><p class=\"amount\" id=\"amount\"></p><p>Response deadline: <span id=\"deadline\"></span></p><p id=\"flags\"></p><h3>Evidence and event history</h3><ul id=\"events\"></ul><button id=\"load-photos\">Load available photos</button><div id=\"photos\"></div><h3>Reasoned decision</h3><label for=\"action\">Decision stage</label><select id=\"action\"><option value=\"decide\">Provisional decision</option><option value=\"finalize\">Independent final review</option></select><label for=\"payout\">Business payout AUD</label><input id=\"payout\" inputmode=\"decimal\"><label for=\"refund\">Customer refund AUD</label><input id=\"refund\" inputmode=\"decimal\"><label for=\"reason\">Reason and evidence assessment</label><textarea id=\"reason\" maxlength=\"4000\"></textarea><label><input id=\"ack\" type=\"checkbox\"> I reviewed the evidence, have no conflict of interest and confirm the exact decision.</label><button id=\"submit\" disabled>Record decision</button></section><p id=\"message\" role=\"status\" aria-live=\"polite\"></p>","(()=>{\n const $=id=>document.getElementById(id);let token=\"\",current=null,busy=false,loaded=new Set();\n const msg=s=>$(\"message\").textContent=s;\n const money=x=>{const n=BigInt(x);return \"AUD $\"+String(n/100n)+\".\"+String(n%100n).padStart(2,\"0\");};\n function cents(s){if(!/^[0-9]{1,13}(?:\\.[0-9]{1,2})?$/.test(s))throw Error(\"Enter an exact AUD amount.\");const [d,c=\"\"]=s.split(\".\"),n=BigInt(d)*100n+BigInt(c.padEnd(2,\"0\"));if(n>9007199254740991n)throw Error(\"Amount exceeds limit\");return Number(n);}\n function clear(){current=null;loaded.clear();$(\"details\").hidden=true;$(\"events\").replaceChildren();$(\"photos\").replaceChildren();$(\"ack\").checked=false;$(\"independent\").checked=false;$(\"reason\").value=\"\";$(\"payout\").value=\"\";$(\"refund\").value=\"\";}\n function controls(){for(const id of [\"load\",\"clear\",\"token\",\"case-ref\",\"open\",\"payout\",\"refund\",\"reason\",\"ack\",\"action\",\"load-photos\",\"independent\",\"assignments\",\"declare\"])$(id).disabled=busy;\n const c=current?.case,phase=$(\"action\").value;\n const eligible=phase===\"decide\"?c?.status===\"open\"&&[\"none\",\"escalated\",\"accepted\"].includes(c.repairPhase):phase===\"finalize\"&&!c?.firstReviewByMe&&(c?.status===\"decided\"&&c.customerAck&&c.ownerAck||c?.status===\"appealed\"&&c.customerAppealEvidence&&c.ownerAppealEvidence);\n const all=c&&[...c.photos,...c.linkedPhotos].every(p=>p.purged||loaded.has(p.source+\":\"+p.photoId));\n $(\"submit\").disabled=busy||!c||!eligible||!all||!c.customerEvidence||!c.ownerEvidence||!$(\"ack\").checked;}\n async function post(action,body){const r=await fetch(\"/v1/securepay-reviewer/\"+action,{method:\"POST\",headers:{\"Content-Type\":\"application/json\",\"Authorization\":\"Bearer \"+token},body:JSON.stringify(body),credentials:\"omit\",cache:\"no-store\",redirect:\"error\"});if(!r.ok)throw Error(\"Access denied\");const x=await r.json();if(x.mode!==\"sandbox\"||x.moneyMoved!==false)throw Error(\"Invalid response\");return x;}\n function line(parent,s){const li=document.createElement(\"li\");li.textContent=s;parent.append(li);}\n async function queue(){const x=await post(\"queue\",{});$(\"queue\").replaceChildren();for(const c of x.cases)line($(\"queue\"),c.severity+\" — \"+c.status+\" — \"+c.repairPhase+\" — due \"+c.dueAt+\" — \"+c.caseId);}\n $(\"load\").addEventListener(\"click\",async()=>{if(busy)return;const supplied=$(\"token\").value.trim();$(\"token\").value=\"\";if(supplied)token=supplied;clear();$(\"queue\").replaceChildren();$(\"assignment-list\").replaceChildren();if(!token){msg(\"Enter a test reviewer MFA token.\");return;}busy=true;controls();try{await queue();msg(\"Assigned cases loaded.\");}catch{msg(\"Queue unavailable.\");}finally{busy=false;controls();}});\n $(\"assignments\").addEventListener(\"click\",async()=>{if(busy||!token)return;busy=true;controls();try{const x=await post(\"assignments\",{});$(\"assignment-list\").replaceChildren();for(const item of x.cases)line($(\"assignment-list\"),item.caseId+\" — eligible \"+item.eligible+\" — declared \"+item.declared);}catch{msg(\"Assignments unavailable.\");}finally{busy=false;controls();}});\n $(\"declare\").addEventListener(\"click\",async()=>{if(busy||!token||!$(\"independent\").checked)return;const id=$(\"case-ref\").value.trim();busy=true;controls();try{await post(\"declare\",{caseId:id,attestation:\"No known personal, financial or professional conflict; I will disclose any change\"});$(\"independent\").checked=false;await queue();msg(\"Independence declaration recorded.\");}catch{msg(\"Declaration not confirmed.\");}finally{busy=false;controls();}});\n $(\"token\").addEventListener(\"input\",()=>{if(!busy){token=\"\";clear();$(\"queue\").replaceChildren();$(\"assignment-list\").replaceChildren();controls();}});\n $(\"case-ref\").addEventListener(\"input\",()=>{if(!busy){clear();controls();}});\n $(\"ack\").addEventListener(\"change\",controls);$(\"action\").addEventListener(\"change\",()=>{$(\"ack\").checked=false;controls();});\n $(\"open\").addEventListener(\"click\",async()=>{if(busy||!token)return;const id=$(\"case-ref\").value.trim();clear();busy=true;controls();try{const x=await post(\"case\",{caseId:id});if(x.review?.case?.caseId!==id)throw Error(\"Invalid case\");current=x.review;const c=current.case;$(\"status\").textContent=c.severity+\" — \"+c.status+\" — \"+c.repairPhase;$(\"amount\").textContent=money(c.amountCents);$(\"deadline\").textContent=c.responseDueAt;$(\"flags\").textContent=\"Customer evidence: \"+c.customerEvidence+\"; owner evidence: \"+c.ownerEvidence;\n for(const e of c.events)line($(\"events\"),e.at+\" — \"+e.role+\" — \"+e.action+\" — \"+e.details+(e.digest?\" — evidence \"+e.digest:\"\"));\n for(const e of c.deadlines)line($(\"events\"),\"Escalated: \"+e.kind+\" — \"+e.dueAt);\n for(const w of c.linkedCompletions??[])line($(\"events\"),\"Completion \"+w.status+\" — \"+w.comments+(w.rejectionReason?\" — rejection: \"+w.rejectionReason:\"\")+\" — manifest \"+w.manifestDigest);\n for(const p of [...c.photos,...c.linkedPhotos])if(p.purged)line($(\"photos\"),\"Retained hash only: \"+p.digest);\n $(\"details\").hidden=false;msg(\"Review case history and load available photographic evidence.\");}catch{clear();msg(\"Case unavailable.\");}finally{busy=false;controls();}});\n $(\"load-photos\").addEventListener(\"click\",async()=>{if(busy||!current)return;busy=true;controls();loaded.clear();$(\"ack\").checked=false;$(\"photos\").replaceChildren();try{for(const p of [...current.case.photos,...current.case.linkedPhotos]){if(p.purged){line($(\"photos\"),\"Retained hash only: \"+p.digest);continue;}const x=await post(\"photo\",{caseId:current.case.caseId,photoId:p.photoId,source:p.source});if(x.photo.photoId!==p.photoId||x.photo.digest!==p.digest)throw Error(\"Photo changed\");const img=document.createElement(\"img\");img.alt=\"Case evidence photograph\";img.src=\"data:image/png;base64,\"+x.photo.content;await img.decode();$(\"photos\").append(img);loaded.add(p.source+\":\"+p.photoId);}msg(\"Available photos loaded.\");}catch{loaded.clear();$(\"photos\").replaceChildren();msg(\"Evidence unavailable; reload the case.\");}finally{busy=false;controls();}});\n $(\"submit\").addEventListener(\"click\",async()=>{if(busy||!current||$(\"submit\").disabled)return;let body;try{const payoutCents=cents($(\"payout\").value.trim()),refundCents=cents($(\"refund\").value.trim()),reason=$(\"reason\").value.trim();if(BigInt(payoutCents)+BigInt(refundCents)!==BigInt(current.case.amountCents)||reason.length<10||reason.length>4000)throw Error(\"Amounts must equal the funded amount and a reason is required.\");body={caseId:current.case.caseId,action:$(\"action\").value,reason,payoutCents,refundCents,stateDigest:current.stateDigest};}catch(e){msg(e.message);return;}busy=true;controls();try{await post(\"decision\",body);clear();await queue();msg(\"Independent decision recorded. No payment authorised or moved.\");}catch{clear();msg(\"Decision not confirmed; reload the case before continuing.\");}finally{busy=false;controls();}});\n $(\"clear\").addEventListener(\"click\",()=>{if(!busy){token=\"\";clear();$(\"queue\").replaceChildren();$(\"assignment-list\").replaceChildren();$(\"token\").value=\"\";$(\"case-ref\").value=\"\";msg(\"Session cleared.\");controls();}});controls();\n})();");}

const governanceScript="(()=>{\n const $=x=>document.getElementById(x),uuid=/^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$/;let token=\"\",busy=false,view=null;\n const msg=s=>$(\"message\").textContent=s,money=s=>{const n=BigInt(s);return \"AUD $\"+String(n/100n)+\".\"+String(n%100n).padStart(2,\"0\");};\n function clear(){view=null;$(\"details\").hidden=true;$(\"summary\").replaceChildren();$(\"agree\").checked=false;$(\"independent\").checked=false;}\n function controls(){for(const id of [\"token\",\"load\",\"clear\",\"case-ref\",\"target\",\"reason\",\"op\",\"apply\",\"declare\",\"read\",\"agree\",\"independent\"])$(id).disabled=busy;$(\"authorize\").disabled=busy||admin||!view||!$(\"agree\").checked||view.case.caseStatus!==\"final\"||view.case.fundingStatus!==\"funded\"||!view.case.independent||!view.case.journalVerified||view.case.unresolved;}\n async function post(action,body){const r=await fetch(\"/v1/securepay-governance/\"+action,{method:\"POST\",headers:{\"Content-Type\":\"application/json\",Authorization:\"Bearer \"+token},body:JSON.stringify(body),cache:\"no-store\",credentials:\"omit\",redirect:\"error\"});if(!r.ok)throw Error(\"Access denied\");const x=await r.json();if(x.mode!==\"sandbox\"||x.moneyMoved!==false)throw Error(\"Invalid response\");return x;}\n function line(parent,s){const li=document.createElement(\"li\");li.textContent=s;parent.append(li);}\n async function queue(){const x=await post(\"queue\",{});$(\"queue\").replaceChildren();for(const c of x.cases){line($(\"queue\"),c.caseId+\" — \"+c.severity+\" — \"+c.status+(admin?\" — governed \"+c.governed:\" — eligible \"+c.eligible+\" — declaration \"+c.declared));if(admin)for(const a of c.assignments)line($(\"queue\"),a.actorId+\" — \"+a.role+\" — declared \"+a.declared+\" — revoked \"+a.revoked+\" — conflict \"+a.conflict);}}\n $(\"load\").addEventListener(\"click\",async()=>{if(busy)return;const supplied=$(\"token\").value.trim();$(\"token\").value=\"\";if(supplied)token=supplied;clear();$(\"queue\").replaceChildren();if(!token){msg(\"Enter assigned MFA test token.\");return;}busy=true;controls();try{await queue();msg(\"Case queue loaded.\");}catch{msg(\"Queue unavailable.\");}finally{busy=false;controls();}});\n $(\"token\").addEventListener(\"input\",()=>{if(!busy){token=\"\";clear();$(\"queue\").replaceChildren();controls();}});$(\"case-ref\").addEventListener(\"input\",()=>{if(!busy){clear();controls();}});$(\"agree\").addEventListener(\"change\",controls);\n for(const [id,action] of [[\"apply\",\"action\"],[\"declare\",\"declare\"],[\"read\",\"read\"],[\"authorize\",\"authorize\"]])$(id).addEventListener(\"click\",async()=>{\n  if(busy||!token||$(id).disabled)return;const caseId=$(\"case-ref\").value.trim();let body={caseId};if(!uuid.test(caseId)){msg(\"Enter a case reference.\");return;}\n  if(id===\"apply\"){const action=$(\"op\").value,reason=$(\"reason\").value.trim(),target=action===\"enroll\"?null:$(\"target\").value.trim();if(reason.length<10||reason.length>1000||(target!==null&&!uuid.test(target))){msg(\"Enter a reason and valid actor reference.\");return;}body={caseId,target,action,reason};}\n  if(id===\"declare\"){if(!$(\"independent\").checked){msg(\"Confirm the independence declaration.\");return;}body.attestation=\"No known personal, financial or professional conflict; I will disclose any change\";}\n  if(id===\"authorize\"){if(view?.case.caseId!==caseId)return;body={caseId,payoutCents:Number(view.case.payoutCents),refundCents:Number(view.case.refundCents),stateDigest:view.stateDigest};}\n  busy=true;controls();try{const x=await post(action,body);clear();\n   if(id===\"read\"){view=x.review;const c=view.case;if(c.caseId!==caseId)throw Error(\"Scope mismatch\");line($(\"summary\"),\"Case \"+c.caseStatus+\" — funding \"+c.fundingStatus);line($(\"summary\"),\"Amount \"+money(c.amountCents)+\" — remaining \"+money(c.remainingCents));line($(\"summary\"),\"Journal verified \"+c.journalVerified+\" — independent \"+c.independent+\" — unresolved issues \"+c.unresolved);if(c.decision)line($(\"summary\"),\"Final decision: \"+c.decision.reason+\" — payout \"+money(c.payoutCents)+\" — refund \"+money(c.refundCents)+\" — evidence \"+c.decision.digest);for(const l of c.legs)line($(\"summary\"),l.kind+\" — \"+money(l.amountCents)+\" — \"+l.status);$(\"details\").hidden=false;msg(\"Review exact settlement and current financial status.\");}\n   else{await queue();msg(id===\"authorize\"?\"Settlement authorized for separate provider processing. No money moved.\":\"Governance action recorded.\");}\n  }catch{clear();msg(\"Action not confirmed. Reload before continuing.\");}finally{busy=false;controls();}\n });\n $(\"clear\").addEventListener(\"click\",()=>{if(!busy){token=\"\";clear();$(\"queue\").replaceChildren();for(const id of [\"token\",\"case-ref\",\"target\",\"reason\"])$(id).value=\"\";msg(\"Session cleared.\");controls();}});controls();\n})();";
const governanceMarkup="<h1>SecurePay GOVERNANCE_TITLE</h1><p class=\"notice\">SANDBOX ONLY. No live payment execution.</p><section><label for=\"token\">Assigned MFA test token</label><input id=\"token\" type=\"password\" autocomplete=\"off\"><button id=\"load\">Load case queue</button><button id=\"clear\">Clear session</button><ol id=\"queue\"></ol><label for=\"case-ref\">Case reference</label><input id=\"case-ref\"><div ADMIN><label for=\"op\">Administration action</label><select id=\"op\"><option value=\"enroll\">Enroll open case in governance</option><option value=\"assign\">Assign reviewer or authorizer</option><option value=\"revoke\">Revoke assignment</option><option value=\"conflict\">Record conflict and revoke</option></select><label for=\"target\">Provisioned actor reference (not required for enrollment)</label><input id=\"target\"><label for=\"reason\">Documented rationale</label><textarea id=\"reason\" maxlength=\"1000\"></textarea><button id=\"apply\">Record action</button></div><div SETTLEMENT><label><input id=\"independent\" type=\"checkbox\"> I declare no known personal, financial or professional conflict and will disclose any change.</label><button id=\"declare\">Record independence declaration</button><button id=\"read\">Inspect settlement</button><section id=\"details\" hidden><ul id=\"summary\"></ul><label><input id=\"agree\" type=\"checkbox\"> I confirm the exact displayed final decision and amounts.</label><button id=\"authorize\" disabled>Authorize exact settlement</button></section></div></section><p id=\"message\" role=\"status\" aria-live=\"polite\"></p>";
